args.query:
MATCH (d:Decision)-[:OWNED_BY]->(p:Person)
WHERE p.left IS NOT NULL
AND NOT EXISTS { MATCH (x:Decision)-[:SUPERSEDES]->(d) }
AND EXISTS { MATCH (d)-[:DEPENDS_ON]->(r:Decision) WHERE EXISTS { MATCH (y:Decision)-[:SUPERSEDES]->(r) } }
RETURN d.id AS id, d.title AS title, p.name AS owner

