args.query:
MATCH (a:Decision)-[ca:CONSTRAINS]->(t:Technology)<-[cb:CONSTRAINS]-(b:Decision)
WHERE ca.stance='forbids' AND cb.stance IN ['requires','allows'] AND a.id<>b.id
AND (ca.scope=cb.scope OR ca.scope='all' OR cb.scope='all')
AND NOT EXISTS { (x:Decision)-[:SUPERSEDES]->(a) }
AND NOT EXISTS { (y:Decision)-[:SUPERSEDES]->(b) }
RETURN DISTINCT a.id AS forbid, b.id AS other, t.name AS tech, ca.scope AS s1, cb.scope AS s2, cb.stance AS st ORDER BY tech

